/* 青橙小说 签名库 (QC) —— 静态票据 + 按 path/query/body 重算 sign
   逆向自 com.qingcheng.reader 5.0.1.1 / libnative-lib.so
   _s   = MD5(deviceId+userId) 固定
   sign = HMAC-SHA256(KEY, path+encodedQuery+"&"+R0+"&"+排序POST参数(解一层URL编码))
   _p   = URLEncode(DES/ECB/NoPadding(DESK, R0+"&sign="+sign + \u0001填充到8倍数)) Base64
   注: R0 内 uth 依赖旧 time, 故 time 必须固定为抓包时刻; 服务端实测无时间窗口(40min+仍有效)
*/
var QC_KEY='NiozHhg/lMm5ja-DVEV_jzk$,t0B4*$5';
var QC_DESK='snY%169j';
var QC_R0='utId=&deviceId=ylms&userId=y233108512&sex=unknown&tmpToken=18ed8908ad0749d2ab6e1dc91f055eec&st=4&uth=21920cda455ba0f3883dc675899c5354&oaid=&udid=';
var QC_COMMON='platId=2&appId=com.qingcheng.reader&channelId=qingchengxs&appVersion=5.0.1&srcChannelId=qingchengxs&time=1794411627&_s=0D8E1B4226B86B69A867999DE9F2C505&mode=1&verCode=5000101&insTs=1794411459';
var QC_B64='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
function QC_b64(x){var o='';for(var i=0;i<x.length;i+=3){var a=x[i]&255,b=i+1<x.length?x[i+1]&255:0,c=i+2<x.length?x[i+2]&255:0,n=(a<<16)|(b<<8)|c;o+=QC_B64.charAt((n>>18)&63)+QC_B64.charAt((n>>12)&63)+(i+1<x.length?QC_B64.charAt((n>>6)&63):'=')+(i+2<x.length?QC_B64.charAt(n&63):'=');}return o;}
function QC_dec1(s){var o='';for(var i=0;i<s.length;i++){if(s.charAt(i)==='%'&&i+2<s.length){var h=s.slice(i+1,i+3);if(/^[0-9a-fA-F]{2}$/.test(h)){o+=String.fromCharCode(parseInt(h,16));i+=2;continue;}}o+=s.charAt(i);}return o;}
function QC_hm(s){var m=Packages.javax.crypto.Mac.getInstance('HmacSHA256');m.init(new Packages.javax.crypto.spec.SecretKeySpec(new Packages.java.lang.String(QC_KEY).getBytes('UTF-8'),'HmacSHA256'));var d=m.doFinal(new Packages.java.lang.String(s).getBytes('UTF-8'));var o='';for(var i=0;i<d.length;i++){var h=(d[i]&255).toString(16);o+=h.length<2?'0'+h:h;}return o;}
function QC_ec(s){var c=Packages.javax.crypto.Cipher.getInstance('DES/ECB/NoPadding');c.init(Packages.javax.crypto.Cipher.ENCRYPT_MODE,new Packages.javax.crypto.spec.SecretKeySpec(new Packages.java.lang.String(QC_DESK).getBytes('UTF-8'),'DES'));return QC_b64(c.doFinal(new Packages.java.lang.String(s).getBytes('UTF-8')));}
function QC_jurl(s){return String(Packages.java.net.URLEncoder.encode(s,'UTF-8'));}
function QC_sign(path,queryExtra,body){
  var q=QC_COMMON+(queryExtra?'&'+queryExtra:'');
  var d={},ps=String(body||'').split('&');
  for(var i=0;i<ps.length;i++){var p=ps[i].indexOf('=');if(p>0)d[ps[i].slice(0,p)]=QC_dec1(ps[i].slice(p+1));}
  var ks=[];for(var k in d)ks.push(k);ks.sort();
  var so=[];for(var i=0;i<ks.length;i++)if(d[ks[i]]!=='')so.push(ks[i]+'='+d[ks[i]]);
  var plain=QC_R0+'&sign='+QC_hm(path+q+'&'+QC_R0+'&'+so.join('&'));
  var L=new Packages.java.lang.String(plain).getBytes('UTF-8').length;
  while(L%8!==0){plain+='\u0001';L++;}
  return path+'?'+q+'&_p='+QC_jurl(QC_ec(plain));
}

/* QC_url: 纯函数, 返回带签名的完整 URL (不含 java 绑定) */
function QC_url(path, qe, body, host){
  return 'https://' + (host || 'goway.reader.yueyouxs.com') + QC_sign(path, qe, body);
}
function QC_opt(body){
  return JSON.stringify({"method":"POST","headers":{"Content-Type":"application/x-www-form-urlencoded","User-Agent":"okhttp/4.10.0"},"body":body});
}
function QC_clean(s){ return String(s==null?'':s).replace(/<[^>]*>/g,'').replace(/&nbsp;/g,' ').replace(/&amp;/g,'&'); }
function QC_post(path, qe, body, host, jv){
  return String(jv.ajax(QC_url(path,qe,body,host) + ',' + QC_opt(body)));
}

