  var body='bookId=272713&needChapter=0&needRecommend=0',ok=false,ms=0,code='?',t0=Date.now();
  try{
    var u='https://goway.reader.yueyouxs.com'+QC_sign('/goway/goread/app/book/detail','',body);
    var o=JSON.stringify({"method":"POST","headers":{"Content-Type":"application/x-www-form-urlencoded","User-Agent":"okhttp/4.10.0"},"body":body});
    var s=String(jv.ajax(u+','+o)); ms=Date.now()-t0;
    try{code=String(JSON.parse(s).code);}catch(e){}
    ok=(code==='0');
  }catch(e){}
  var state=ok?'✅ 游客态可用（本源无需登录）':'❌ 接口异常 code='+code;
  return QC_tip(jv,'登录状态：'+state+'｜票据 _s 静态有效｜延时 '+ms+'ms','qcStatus',(ok?'游客态OK':'异常')+' '+ms+'ms');
}
/* ② 官方 API 线路延时测试(单域, ms 写入状态按钮) */
function QC_testMs(jv){
  QC_tip(jv,'⏳ 正在测试官方 API 线路延时…','qcStatus','测速中…');
  var body='bookId=272713&needChapter=0&needRecommend=0',ms='失败',ok=false;
  var t0=Date.now();
  try{
    var u='https://goway.reader.yueyouxs.com'+QC_sign('/goway/goread/app/book/detail','',body);
    var o=JSON.stringify({"method":"POST","headers":{"Content-Type":"application/x-www-form-urlencoded","User-Agent":"okhttp/4.10.0"},"body":body});
    var s=String(jv.ajax(u+','+o));
    ok=(s.indexOf('"code":0')>=0&&s.indexOf('bookName')>=0);
    ms=ok?String(Date.now()-t0)+'ms':'不可用';
  }catch(e){}
  jv.put('qcSpeed',ms);
  return QC_tip(jv,(ok?'✅ 官方线路正常 ':'❌ 官方线路异常 ')+ms,'qcStatus','官方线路 '+ms);
}
